SELECT COUNT(SalesOrderID) AS TotalOrders
FROM Sales.SalesOrderHeader
WHERE OrderDate >= '2012-01-01' AND OrderDate < '2013-01-01' AND Status = 5;

SELECT SUM(Freight) AS TotalFreight
FROM Sales.SalesOrderHeader
WHERE OrderDate >= '2012-01-01' AND OrderDate < '2013-01-01';

SELECT SUM(SalesOrderHeader.SubTotal) AS TotalRevenue
FROM Sales.SalesOrderHeader
WHERE SalesOrderHeader.Status = 5;

SELECT COUNT(DISTINCT CustomerID) AS NumberOfCustomers
FROM Sales.SalesOrderHeader
WHERE Status = 5;

SELECT COUNT(SalesOrderID) AS NumberOfOnlineOrders
FROM Sales.SalesOrderHeader
WHERE OnlineOrderFlag = 1 AND Status = 5;

SELECT COUNT(SalesOrderID) AS TotalOrders
FROM Sales.SalesOrderHeader
WHERE OrderDate >= '2013-07-01' AND OrderDate < '2013-10-01' AND Status = 5;

SELECT COUNT(SalesOrderID) AS NumberOfOrders
FROM Sales.SalesOrderHeader
WHERE OrderDate >= '2013-12-01' AND OrderDate < '2014-01-01';

SELECT SUM(TotalDue) AS TotalPayment
FROM Sales.SalesOrderHeader
WHERE Status = 5 AND OrderDate >= '2013-01-01' AND OrderDate < '2014-01-01';

